import reportsJson from "@/data/fia-reports.json";

/**
 * The FIA's published papers for the next race, as saved by
 * `scripts/fia-reports.mjs`.
 *
 * The JSON is generated by the daily GitHub Action, committed, and imported
 * here at build time — so the page is static, costs nothing per view, and no
 * model is called when somebody refreshes it.
 */

export type ReportImpact =
  | "upgrade"
  | "penalty"
  | "power-unit"
  | "scrutineering"
  | "decision"
  | "result"
  | "briefing"
  | "entry"
  | "other";

export type Significance = "high" | "medium" | "low";

export type FiaDocument = {
  id: string;
  doc: number | null;
  title: string;
  url: string;
  publishedAt: string | null;
  publishedLabel: string;
  eventName?: string;
  impact: ReportImpact;
  team: string | null;
  teamLabel: string | null;
  drivers: string[];
  headline: string;
  detail: string;
  significance: Significance;
  source: "ai" | "rules";
};

export type FiaReports = {
  generatedAt: string;
  event: {
    name: string;
    round: number;
    raceName: string;
    circuitId: string;
    date: string;
  } | null;
  sourceUrl: string;
  latestPublishedAt: string | null;
  model: string | null;
  read: string | null;
  readSource: "ai" | "rules" | null;
  teams: Array<{ team: string; flag: "upgrade" | "penalty" | "info"; note: string }>;
  documents: FiaDocument[];
};

export const REPORTS = reportsJson as unknown as FiaReports;

export const IMPACT_LABEL: Record<ReportImpact, string> = {
  upgrade: "Upgrade",
  penalty: "Penalty",
  "power-unit": "Power unit",
  scrutineering: "Scrutineering",
  decision: "Stewards",
  result: "Result",
  briefing: "Briefing",
  entry: "Entry",
  other: "Other",
};

export const IMPACT_ORDER: ReportImpact[] = [
  "upgrade",
  "power-unit",
  "penalty",
  "decision",
  "scrutineering",
  "result",
  "entry",
  "briefing",
  "other",
];

export function eventDocuments(name?: string): FiaDocument[] {
  const target = name ?? REPORTS.event?.name;
  if (!target) return [];
  return REPORTS.documents.filter((doc) => doc.eventName === target);
}

/** The documents worth a fan's attention, strongest first. */
export function watchDocuments(limit = 4): FiaDocument[] {
  const weight: Record<Significance, number> = { high: 0, medium: 1, low: 2 };
  const notable = eventDocuments().filter(
    (doc) => doc.impact === "penalty" || doc.impact === "upgrade" || doc.impact === "power-unit" || doc.impact === "decision",
  );
  return [...notable]
    .sort(
      (a, b) =>
        weight[a.significance] - weight[b.significance] ||
        (b.publishedAt ?? "").localeCompare(a.publishedAt ?? ""),
    )
    .slice(0, limit);
}

export function eventLabel(name?: string): string {
  if (!name) return "the weekend";
  return name;
}

export function reportDate(value: string | null): string {
  if (!value) return "—";
  return new Date(value).toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
  });
}
